import { CommonModule } from '@angular/common';
import { Component, OnDestroy, OnInit } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { Subscription } from 'rxjs';
import { FormsRenderService } from 'src/app/shared/services/forms-render/forms-render-service';

@Component({
  selector: 'mf-forms-renderer',
  templateUrl: './renderer.component.html',
  standalone: true,
  imports: [ReactiveFormsModule, MatFormFieldModule, CommonModule, MatInputModule],
  styleUrls: ['./renderer.component.scss'],
})
export class RendererComponent implements OnInit, OnDestroy {
  jsonData: Array<Object> = [];
  saidaEsperada: any = {};
  saidaEsperadaString: string = '';
  meuValor: string = 'string';
  form = new FormGroup({
    autoResize: new FormControl(''),
  });
  private subscription!: Subscription;
  data$ = this.formsRenderService.data$;
  constructor(private formsRenderService: FormsRenderService) {}
  ngOnInit(): void {
    this.subscription = this.formsRenderService.data$.subscribe(
      (value) => {
        this.jsonData = value;
        console.log('renderer', this.jsonData);
      }
    );
  }
  ngOnDestroy(): void {
    this.subscription.unsubscribe();
  }
  onChangeDynamicForm(event: Event) {
    let eventData = event.target as HTMLInputElement;
    let data: any = {};
    if (eventData.id.includes('.')) {
      let eventDataParts = eventData.id.split('.');
      eventDataParts.forEach((item: string, i: number) => {
        if (i === eventDataParts.length - 1) {
          data[item] = eventData.value;
        }
        if (i !== 0) {
          data = data[item];
        } else {
          data = this.saidaEsperada;
        }
      });
    } else {
      this.saidaEsperada[eventData.id] = eventData.value;
    }
    this.saidaEsperadaString = JSON.stringify(this.saidaEsperada);
  }
}
<p>renderer</p>

<div class="ids-col-4 ids-col-sm-8 ids-col-md-4 ids-card -variant card-width'">
  <p>Seu formulário ficará assim</p>
  <p>"""{{ jsonData }}"""</p>
  <form [formGroup]="form" autocomplete="off">
    <p>hello1</p>
    <ng-container *ngIf="data$ | async as data">
      <p>hello {{data}}hello</p>
      <ng-container *ngIf="data && data.length > 0">
        <p>hello3</p>
        <div *ngFor="let propriedade of data">
          <!-- {{ propriedade.rotulo }} -->
          <div *ngIf="propriedade.tipo_dado === 'array'">
            <mat-form-field *ngFor="let item of propriedade.conteudo">
              <input
                matInput
                id="array.{{ propriedade.contrato }}.{{ item.contrato }}"
                formControlName="requiredWithHelper"
                (change)="onChangeDynamicForm($event)"
              />
            </mat-form-field>
          </div>
        </div>
      </ng-container>
    </ng-container>
  </form>
</div>
